'use client'

import { useRef, type ReactNode } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type MagneticHoverProps = {
  children: ReactNode
  className?: string
  strength?: number
  duration?: number
  disabled?: boolean
}

export function MagneticHover({
  children,
  className,
  strength = 0.25,
  duration = 0.35,
  disabled = false,
}: MagneticHoverProps) {
  const root = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()

  useGSAP(
    ({ gsap }) => {
      const element = root.current
      if (
        !element ||
        disabled ||
        reduced ||
        prefersReducedMotion() ||
        !window.matchMedia('(pointer: fine)').matches
      ) {
        return
      }

      const xTo = gsap.quickTo(element, 'x', { duration, ease: 'power3.out' })
      const yTo = gsap.quickTo(element, 'y', { duration, ease: 'power3.out' })

      const move = (event: PointerEvent): void => {
        const bounds = element.getBoundingClientRect()
        xTo((event.clientX - (bounds.left + bounds.width / 2)) * strength)
        yTo((event.clientY - (bounds.top + bounds.height / 2)) * strength)
      }

      const reset = (): void => {
        xTo(0)
        yTo(0)
      }

      element.addEventListener('pointermove', move)
      element.addEventListener('pointerleave', reset)
      element.addEventListener('pointercancel', reset)

      return () => {
        element.removeEventListener('pointermove', move)
        element.removeEventListener('pointerleave', reset)
        element.removeEventListener('pointercancel', reset)
      }
    },
    [disabled, duration, reduced, strength],
    root,
  )

  return (
    <div ref={root} className={className}>
      {children}
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

'use client'

import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useEffect, type DependencyList, type RefObject } from 'react'

let registered = false

function ensureGsapPlugins(): void {
  if (typeof window === 'undefined' || registered) return
  gsap.registerPlugin(ScrollTrigger)
  registered = true
}

export type GSAPTools = {
  gsap: typeof gsap
  ScrollTrigger: typeof ScrollTrigger
}

export type GSAPCallback = (tools: GSAPTools) => void | (() => void)

export function useGSAP(
  callback: GSAPCallback,
  deps: DependencyList = [],
  scope?: RefObject<Element | null>,
): void {
  useEffect(() => {
    if (typeof window === 'undefined') return

    ensureGsapPlugins()

    let dispose: void | (() => void)
    const context = gsap.context(() => {
      dispose = callback({ gsap, ScrollTrigger })
    }, scope?.current ?? undefined)

    return () => {
      dispose?.()
      context.revert()
    }

    // Dependencies are deliberately controlled by each animation consumer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
